referenceSolutions.python:
def dispatchOrderEvenKeyCensus(links, k):
    a=links
    out=[]
    from collections import deque
    n=len(a)
    degree=[sum(row[v] for row in a) for v in range(n)]
    queue=deque(v for v in range(n) if degree[v]==0)
    while queue:
        u=queue.popleft()
        out.append(u)
        for v in range(n):
            if a[u][v]:
                degree[v]-=1
                if degree[v]==0: queue.append(v)
    if len(out)!=n: out=[]
    return sum(x%2==0 for x in out)

